Draw.loadPlugin(function(ui) {
  ui.actions.addAction('hello', function() {
    ui.editor.graph.insertVertex(ui.editor.graph.getDefaultParent(), null, 'Hello', 40, 40, 120, 60, 'rounded=1;whiteSpace=wrap;html=1;');
  });
  var menu = ui.menus.get('extras');
  var oldFunct = menu.funct;
  menu.funct = function(m, parent) { oldFunct.apply(this, arguments); ui.menus.addMenuItems(m, ['-', 'hello'], parent); };
});

