var graph = ui.editor.graph, model = graph.getModel();
model.beginUpdate();
try {
  var v1 = graph.insertVertex(graph.getDefaultParent(), null, 'A', 20, 20, 80, 40, 'rounded=1;html=1;');
  var v2 = graph.insertVertex(graph.getDefaultParent(), null, 'B', 200, 20, 80, 40, 'ellipse;html=1;');
  graph.insertEdge(graph.getDefaultParent(), null, '', v1, v2, 'edgeStyle=orthogonalEdgeStyle;html=1;');
} finally { model.endUpdate(); }

